-- Reference schema: the app creates its local SQLite tables in lib/data/azar_db.dart.
CREATE TABLE parties(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, phone TEXT, role TEXT NOT NULL DEFAULT 'both', opening_balance INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE vehicles(id INTEGER PRIMARY KEY AUTOINCREMENT, plate TEXT NOT NULL, driver TEXT, phone TEXT, created_at TEXT NOT NULL);
CREATE TABLE transactions(id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, date TEXT NOT NULL, party_id INTEGER, vehicle_id INTEGER, material TEXT, gross_kg INTEGER NOT NULL DEFAULT 0, tare_kg INTEGER NOT NULL DEFAULT 0, net_ton REAL NOT NULL DEFAULT 0, unit_price INTEGER NOT NULL DEFAULT 0, material_amount INTEGER NOT NULL DEFAULT 0, freight INTEGER NOT NULL DEFAULT 0, freight_mode TEXT NOT NULL DEFAULT 'separate', final_amount INTEGER NOT NULL DEFAULT 0, weigh_ticket TEXT, note TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, is_void INTEGER NOT NULL DEFAULT 0);
CREATE TABLE payments(id INTEGER PRIMARY KEY AUTOINCREMENT, party_id INTEGER NOT NULL, date TEXT NOT NULL, direction TEXT NOT NULL, amount INTEGER NOT NULL, method TEXT NOT NULL, reference TEXT, cheque_status TEXT, note TEXT, created_at TEXT NOT NULL);
CREATE TABLE audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT, entity TEXT NOT NULL, entity_id INTEGER, action TEXT NOT NULL, before_json TEXT, after_json TEXT, at TEXT NOT NULL);
